package com.example.data.subtitles

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/** Contratto dell'audit sottotitoli ASS/SSA e formati a cue. */
class SubtitleAuditEngineTest {

  private val assSample = """
    [Script Info]
    ; Script generated by Aegisub
    ScriptType: v4.00+
    PlayResX: 1920
    PlayResY: 1080
    WrapStyle: 0

    [V4+ Styles]
    Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
    Style: Default,Open Sans,48,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1
    Style: Top,Bebas Neue,40,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,8,10,10,10,1

    [Events]
    Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
    Dialogue: 0,0:00:01.00,0:00:03.00,Default,,0,0,0,,{\pos(960,980)}Ciao a tutti
    Dialogue: 0,0:00:03.50,0:00:06.00,Default,,0,0,0,,{\k20}Kara{\k30}oke
  """.trimIndent()

  private val ssaSample = """
    [Script Info]
    ScriptType: v4.00
    PlayResX: 640
    PlayResY: 480

    [V4 Styles]
    Format: Name, Fontname, Fontsize
    Style: Default,Arial,20

    [Events]
    Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Test
  """.trimIndent()

  private val srtSample = """
    1
    00:00:01,000 --> 00:00:03,000
    Ciao

    2
    00:00:04,000 --> 00:00:06,000
    Mondo
  """.trimIndent()

  private val vttSample = """
    WEBVTT

    00:01.000 --> 00:03.000
    Ciao

    00:04.000 --> 00:06.000
    Mondo
  """.trimIndent()

  @Test
  fun `detects ass format and rich features`() {
    val audit = SubtitleAuditEngine.audit(assSample)
    assertEquals(SubtitleContainerFormat.ASS, audit.format)
    assertEquals("v4.00+", audit.scriptType)
    assertEquals(1920, audit.playResX)
    assertEquals(1080, audit.playResY)
    assertEquals(2, audit.styleCount)
    assertEquals(2, audit.cueCount)
    assertTrue(audit.hasPositioning)
    assertTrue(audit.hasKaraoke)
    assertTrue(audit.hasOverrides)
    assertTrue(audit.isAssFamily)
    assertTrue(audit.hasLossyFeatures)
    assertTrue(audit.summary.contains("ASS"))
    assertTrue(audit.summary.contains("2 stili"))
  }

  @Test
  fun `ass fonts not embedded produce warning`() {
    val audit = SubtitleAuditEngine.audit(assSample)
    assertTrue(audit.referencedFonts.contains("Open Sans"))
    assertTrue(audit.embeddedFonts.isEmpty())
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.FONTS_NOT_EMBEDDED))
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.POSITIONING_IGNORED))
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.KARAOKE_FLATTENED))
  }

  @Test
  fun `detects legacy ssa format`() {
    val audit = SubtitleAuditEngine.audit(ssaSample)
    assertEquals(SubtitleContainerFormat.SSA, audit.format)
    assertEquals(1, audit.cueCount)
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.NO_PLAYRES).not())
  }

  @Test
  fun `detects srt and counts cues`() {
    val audit = SubtitleAuditEngine.audit(srtSample)
    assertEquals(SubtitleContainerFormat.SUBRIP, audit.format)
    assertEquals(2, audit.cueCount)
    assertFalse(audit.isAssFamily)
    assertTrue(audit.warnings.isEmpty())
  }

  @Test
  fun `detects webvtt`() {
    val audit = SubtitleAuditEngine.audit(vttSample)
    assertEquals(SubtitleContainerFormat.WEBVTT, audit.format)
    assertEquals(2, audit.cueCount)
  }

  @Test
  fun `detects ttml`() {
    val audit = SubtitleAuditEngine.audit(
      "<?xml version=\"1.0\"?><tt xmlns=\"http://www.w3.org/ns/ttml\"><body><p begin=\"0s\" end=\"2s\">Ciao</p></body></tt>"
    )
    assertEquals(SubtitleContainerFormat.TTML, audit.format)
    assertTrue(audit.cueCount >= 1)
  }

  @Test
  fun `detects utf8 bom and utf16 bytes`() {
    val utf8Bom = byteArrayOf(0xEF.toByte(), 0xBB.toByte(), 0xBF.toByte()) + srtSample.toByteArray()
    assertEquals(SubtitleEncoding.UTF_8_BOM, SubtitleAuditEngine.audit(utf8Bom).encoding)

    val utf16 = srtSample.toByteArray(Charsets.UTF_16LE)
    val withBom = byteArrayOf(0xFF.toByte(), 0xFE.toByte()) + utf16
    val audit = SubtitleAuditEngine.audit(withBom)
    assertEquals(SubtitleEncoding.UTF_16_LE, audit.encoding)
    assertEquals(SubtitleContainerFormat.SUBRIP, audit.format)
  }

  @Test
  fun `empty input is reported honestly`() {
    val audit = SubtitleAuditEngine.audit("")
    assertEquals(SubtitleContainerFormat.UNKNOWN, audit.format)
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.EMPTY_FILE))
  }

  @Test
  fun `drawing commands are flagged`() {
    val ass = assSample.replace(
      "{\\pos(960,980)}Ciao a tutti",
      "{\\p1}m 0 0 l 100 0 100 100 0 100{\\p0}"
    )
    val audit = SubtitleAuditEngine.audit(ass)
    assertTrue(audit.hasDrawing)
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.DRAWING_FLATTENED))
  }

  @Test
  fun `many styles warning above threshold`() {
    val styles = (1..30).joinToString("\n") {
      "Style: S$it,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1"
    }
    val file = """
      [Script Info]
      ScriptType: v4.00+
      PlayResX: 1920
      PlayResY: 1080
      [V4+ Styles]
      $styles
      [Events]
      Dialogue: 0,0:00:01.00,0:00:02.00,S1,,0,0,0,,Test
    """.trimIndent()
    val audit = SubtitleAuditEngine.audit(file)
    assertEquals(30, audit.styleCount)
    assertTrue(audit.warnings.contains(SubtitleAuditWarning.MANY_STYLES))
  }
}
